using System;using System.IO;using System.Linq;using System.Text;using System.Threading;using System.Threading.Tasks;using System.Windows.Forms;
namespace GearLab {
 public static class AuthorRobotViewTests {
  static int checks;static void Check(bool x,string s){checks++;if(!x)throw new Exception(s);}
  static void Wait(Func<bool> x,string s){var watch=System.Diagnostics.Stopwatch.StartNew();while(!x()&&watch.Elapsed.TotalSeconds<120){Application.DoEvents();Thread.Sleep(15);}Check(x(),s);}
  static T Get<T>(Task<T> t){Wait(()=>t.IsCompleted,"viewport operation");return t.GetAwaiter().GetResult();}
  static void Shot(RobotDesignerForm robot,string path){var until=DateTime.UtcNow.AddMilliseconds(450);Wait(()=>DateTime.UtcNow>until,"render settled");var t=robot.WebScene.SavePreview(path);Wait(()=>t.IsCompleted,"preview capture");t.GetAwaiter().GetResult();}
  public static int Run(string folder){Directory.CreateDirectory(folder);var settings=AppSettings.Current;try{AppSettings.Current=new AppSettings{AutoSave=false};var d=RobotDocument.DefaultReference();Check(d.Joints.Count==6&&d.Joints.All(j=>j.BodyGenerator.BlenderDesign),"author preset is default");Check(d.Joints.All(j=>j.GeneratedBody!=null&&j.GeneratedBody.Fingerprint==ProceduralBodySpec.Fingerprint(d,j,j.BodyGenerator)),"all native cached parts current");
   var pose=d.Clone();double[] angles={0,30,60,0,35,0};for(int i=0;i<6;i++)pose.Joints[i].Position=angles[i];var build=RobotCad.Build(pose);Check(build.Model.Valid&&RobotConnections.Validate(build).Count==0,"bent pose remains joined");
   using(var kernel=new CADKernel()){var parts=build.Entries.Values.Where(e=>!e.Guide&&e.Category!="Крепёж"&&e.Category!="Проводка").Select(e=>new{Id=e.Id,Step=CADNativeBridge.FromLegacyPart(e.Part).Features[0].Data,Transform=CADNativeBridge.Transform(build.Pose(e.Id,0,false)),Integral=e.Category=="Мотор"?e.JointId+"_motor_integral":null}).ToArray();var report=kernel.Run(new CADDocument(),"assembly_contacts",null,null,null,new System.Collections.Generic.Dictionary<string,object>{{"Spec",new{Parts=parts}}}).Motion;File.WriteAllText(Path.Combine(folder,"bent-contacts.json"),CADDocument.Serializer().Serialize(report),Encoding.UTF8);Check(report.Status=="clear","bent CAD intersections: "+string.Join("; ",report.Collisions.Select(c=>c.A+" / "+c.B+" "+c.Volume)));}
   using(var robot=new RobotDesignerForm())using(var shell=new WorkspaceShell(robot)){robot.SetDocument(d);shell.Show();Wait(()=>robot.WebScene.Ready&&robot.Scene.Ready,"author native view ready");int count=robot.Build.Entries.Values.Count(e=>!e.Guide);Wait(()=>{string text=CADDocument.Serializer().Deserialize<string>(Get(robot.WebScene.Inspect()));return text.Contains("\"parts\":"+count)&&text.Contains("triangles");},"all actual mesh parts loaded");robot.SetStage(2);robot.WebScene.Send(new{type="presentation",enabled=true});robot.WebScene.Send(new{type="preset",view="YZ"});Shot(robot,Path.Combine(folder,"author-side.png"));robot.WebScene.Send(new{type="preset",view="REFERENCE"});Shot(robot,Path.Combine(folder,"author-iso.png"));
    robot.SetDocument(pose);Wait(()=>robot.Scene.Ready,"bent model ready");robot.WebScene.Send(new{type="presentation",enabled=true});robot.WebScene.Send(new{type="preset",view="REFERENCE"});Shot(robot,Path.Combine(folder,"author-bent.png"));
    robot.OpenJointControllers();var j=pose.Joints[1];int meshes=robot.Scene.MeshBuildCount;var before=robot.Build.Current[pose.Joints[2].Id].Origin;robot.JogJoint(j.Id,5);Check(Math.Abs(j.Position-35)<1e-7,"negative Y joint can be jogged");Check((robot.Build.Current[pose.Joints[2].Id].Origin-before).Length>1,"actual child follows negative Y joint");Check(robot.Scene.MeshBuildCount==meshes,"jog needs no CAD mesh rebuild");Check(robot.ControllerCount==6,"six joint controllers visible");var last=pose.Ordered().Last();var actual=robot.Build.Pose(last.Id+"_tool_adapter",0,false).Transform(new System.Windows.Media.Media3D.Point3D(0,0,64));Check((actual-RobotSolver.LoadPoint(pose,last,robot.Build.Current)).Length<1e-5,"author tool load point equals the CAD fingertips");Shot(robot,Path.Combine(folder,"author-controllers.png"));shell.ApproveTestClose();shell.Close();}
   File.WriteAllText(Path.Combine(folder,"author-view-results.txt"),"PASS "+checks+" author view assertions: default cached model, clear bent pose, real studio views, six controllers, negative-axis articulation without regeneration, actual fingertip TCP.",Encoding.UTF8);return 0;
  }catch(Exception ex){File.WriteAllText(Path.Combine(folder,"author-view-error.txt"),ex.ToString(),Encoding.UTF8);return 1;}finally{AppSettings.Current=settings;}}
 }
}
